/** The Elsewhere world the import starts from: a real geographic new game on
 * the save's own planet and tile; when the planet cannot be copied tile by
 * tile, a planet generated by Elsewhere from the same seed and coverage with
 * the colony on a tile of the same biome; when no geographic colony is
 * possible (map size), a plain local map. Its local content is then emptied
 * and replaced by the save's. */
import type {World} from '../../sim/types.ts';
import type {RwsSave} from './rws-save.ts';
import type {ImportNotes} from './notes.ts';
import {rebuildPlanet,type PlanetImport} from './planet.ts';
import {BIOME_MAP,worldScale} from './map-world.ts';
import {shortHashTable} from './short-hash.ts';
import {captureGeneratedGeography256} from '../../sim/world-geography-owner-256.ts';
import {createGeographicNewGame256} from '../../sim/geographic-new-game-256.ts';
import {generateGeographicWorldDraft256,type GeographicWorldDraft256} from '../../sim/world-geographic-draft.ts';
import {defaultWorldGenerationSettings,validWorldGenerationSettings,type WorldGenerationSettings} from '../../sim/world-generation-settings.ts';
import {canPlaceWorldSettlement} from '../../sim/world-settlement-placement.ts';
import {ACTUAL_SHRINES_750_256} from '../../sim/ancient-temple-orchestration-256.ts';
import {createStartingCandidateRoster} from '../../sim/starting-candidates.ts';
import {startingOriginalRequestFromRoster256} from '../../sim/starting-original-request-256.ts';
import {validGeographicCreationSize262,type GeographicCreationSize262} from '../../sim/geographic-creation-options-262.ts';
import {stableWorldSeedHash} from '../../sim/world-climate-settings.ts';
import {createWorld,stepWorld} from '../../sim/engine.ts';

export interface BaseWorld {world:World;planetMode:'save'|'seed'|'none';planet?:PlanetImport}
const drain=<Y,T>(it:Generator<Y,T,void>):T=>{let s=it.next();while(!s.done)s=it.next();return s.value;};

/** Advance within the colony stage, 0..1: the generator's own steps, then the pods. */
type ColonyAdvance=(part:number)=>void;
function colonyOn(draft:GeographicWorldDraft256,tile:number,size:GeographicCreationSize262,seed:number,advance:ColonyAdvance=()=>{}):World {
 const geography=captureGeneratedGeography256(draft),roster=createStartingCandidateRoster(seed);
 advance(.1);
 const generation=createGeographicNewGame256({draft,geography,tile,size,scenario:'crashlanded',startingParty:startingOriginalRequestFromRoster256(seed,roster)},{shrines750:ACTUAL_SHRINES_750_256});
 let step=generation.next();
 while(!step.done){const {completed,total}=step.value;if(total>0)advance(.1+.8*Math.min(1,completed/total));step=generation.next();}
 const w=step.value;advance(.92);
 // The starting pods open after a few ticks; the import replaces their people afterwards.
 for(let i=0;i<600&&(w.startingArrival as {phase?:string}|undefined)?.phase!=='opened';i++)stepWorld(w);
 return w;
}

export function createBaseWorld(save:RwsSave,notes:ImportNotes,options:{planet:boolean;onStage?:(stage:'planet'|'colony',part?:number)=>void}):BaseWorld {
 const stage=options.onStage??(()=>{}),advance:ColonyAdvance=part=>stage('colony',part);
 const map=save.maps[0]!,seed=(stableWorldSeedHash(save.world?.seed??'')>>>0)||1;
 if(options.planet){
  const size=map.width;
  if(map.width!==map.height||!validGeographicCreationSize262(size))notes.lost('world',`Carte de ${map.width}×${map.height} : Elsewhere crée les colonies géographiques en carré de 200 à 325 cases ; la carte est importée sans planète.`);
  else{
   stage('planet');
   const planet=rebuildPlanet(save,notes);
   if(planet)try{
    stage('colony');
    const w=colonyOn(planet.draft,planet.homeTile,size,seed,advance);
    notes.mapped('world',`Colonie placée sur la même case de la planète (${planet.homeTile}).`);
    return {world:w,planetMode:'save',planet};
   }catch(error){notes.lost('world',`Création de la colonie sur la planète de la sauvegarde refusée (${error instanceof Error?error.message.slice(0,200):String(error)}).`);}
   // Fallback: Elsewhere's own planet from the same seed and coverage.
   try{
    const seeded=seedPlanet(save,notes);
    if(seeded){stage('colony');const w=colonyOn(seeded.draft,seeded.tile,size,seed,advance);notes.adapted('world',`Planète régénérée par Elsewhere depuis la graine « ${save.world?.seed??''} » : relief, biomes, rivières, routes et factions diffèrent de la partie ; colonie sur la case ${seeded.tile} (${seeded.biome}).`);return {world:w,planetMode:'seed'};}
   }catch(error){notes.lost('world',`Planète régénérée refusée (${error instanceof Error?error.message.slice(0,200):String(error)}).`);}
  }
 }
 const w=createWorld(seed,map.width,map.height);
 notes.adapted('world','Carte importée sans planète (monde local seul).');
 return {world:w,planetMode:'none'};
}

/** Planet from the save's seed and settings; colony on the first admissible
 * tile of the save colony's biome (or any admissible tile). */
function seedPlanet(save:RwsSave,notes:ImportNotes):{draft:GeographicWorldDraft256;tile:number;biome:string}|undefined {
 const world=save.world;if(!world)return undefined;
 const settings={...defaultWorldGenerationSettings(),coverage:Math.round((world.coverage??.3)*100)/100,rainfall:worldScale(world.rainfall),temperature:worldScale(world.temperature),population:worldScale(world.population)} as WorldGenerationSettings;
 if(!validWorldGenerationSettings(settings)){notes.lost('world','Réglages du monde non pris en charge pour régénérer la planète.');return undefined;}
 const player=save.factions.find(f=>f.loadId===save.playerFaction);
 const draft=drain(generateGeographicWorldDraft256({seed:world.seed??'',settings,tick:0,nextThingId:1,playerDef:'PlayerColony',playerName:(player?.name??'Colonie importée').slice(0,80)||'Colonie importée'}));
 const home=save.worldObjects.find(o=>`WorldObject_${o.id}`===save.maps[0]?.parent);
 const biomeName=home&&world.grid?shortHashTable(Object.keys(BIOME_MAP)).get(world.grid.biome[home.tile]!):undefined;
 const wanted=biomeName&&BIOME_MAP[biomeName]&&!('drop' in BIOME_MAP[biomeName]!)?(BIOME_MAP[biomeName] as {to:string}).to:undefined;
 const taken=new Set(draft.factions.settlements.map(s=>s.tile)),tiles=draft.surface.tiles;
 const admissible=(id:number)=>canPlaceWorldSettlement(tiles,id,{settlementTiles:taken});
 const tile=tiles.find(t=>(!wanted||t.biome===wanted)&&admissible(t.id))?.id??tiles.find(t=>admissible(t.id))?.id;
 return tile===undefined?undefined:{draft,tile,biome:tiles[tile]!.biome};
}
